export default {
  id: 'calculator',
  name: 'Calculator',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'sum_values',
        version: '1.0.0',
        description: 'Sum an array of numeric values.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            numbers: { type: 'array', items: { type: 'number' } }
          },
          required: ['numbers'],
          additionalProperties: false
        },
        outputSchema: {
          type: 'object',
          properties: {
            sum: { type: 'number' }
          },
          required: ['sum'],
          additionalProperties: false
        },
        async handler(args: unknown, _tctx: unknown) {
          const { numbers } = args as { numbers: number[] };
          return { ok: true, data: { sum: numbers.reduce((a, b) => a + b, 0) } };
        }
      }
    });
  }
};

